223	    /**
224	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
225	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
226	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
227	     * blank (e.g. {@code "   "}). The offending field names are reported through an
228	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
229	     * as a 400 response carrying an {@code errors} array of field names.
230	     *
231	     * @param ownerFieldsDto the submitted owner fields
232	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
233	     */
234	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
235	        List<String> blankFields = new ArrayList<>();
236	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
237	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
238	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
239	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
240	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
241	        if (!blankFields.isEmpty()) {
242	            throw new InvalidOwnerFieldsException(blankFields);
