266	    /**
267	     * Rejects a create request whose normalized telephone is already used by any existing owner.
268	     * Existing owners' telephones are reduced to the same canonical form (via
269	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
270	     * only in formatting still collide. A collision is reported through a
271	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
272	     * as a 409 Conflict response.
273	     *
274	     * @param normalizedTelephone the canonical telephone of the owner being created
275	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
276	     */
277	    /**
278	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
279	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
280	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
281	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
282	     *
283	     * @param lastName the last name of the owner being created
284	     * @return the formatted customer code
285	     */
286	    private String nextCustomerCode(String lastName) {
287	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
288	        long sequence = this.clinicService.findAllOwners().size() + 1L;
289	        return String.format("%s-%04d", last3, sequence);
290	    }
291	
292	    private void rejectDuplicateTelephone(String normalizedTelephone) {
293	        boolean duplicate = this.clinicService.findAllOwners().stream()
294	            .map(Owner::getTelephone)
295	            .filter(existing -> existing != null)
296	            .map(telephoneNormalizer::canonicalize)
297	            .anyMatch(normalizedTelephone::equals);
298	        if (duplicate) {
299	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
300	        }
301	    }
